-- HANA-SOURCE: cl/bcs/tesoreria/sql/AnularNominasTransferencias_UpdateLiberarMovimientosOriginales.sql
-- H2 rewrite (join chain -> EXISTS).
UPDATE "BSCL.Tesoreria.BD::TES.IngresoEgreso" AS IE SET "IdEstado" = 'ING', "IdUsuarioEmision" = 0, "FechaHoraEmision" = '0001-01-01 00:00:00' WHERE EXISTS (SELECT 1 FROM "BSCL.Tesoreria.BD::TES.ComprobanteDetalleOrigen" AS CDO INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteDetalle" AS CD ON CDO."IdComprobanteDetalle" = CD."IdComprobanteDetalle" INNER JOIN "BSCL.Tesoreria.BD::TES.Comprobante" AS COM ON CD."IdComprobante" = COM."IdComprobante" INNER JOIN "BSCL.Tesoreria.BD::TES.ComprobanteFormaDePago" AS CFP ON COM."IdComprobante" = CFP."IdComprobante" INNER JOIN "BSCL.Tesoreria.BD::TES.NominaTransferencia" AS NT ON CFP."IdComprobantePartida" = NT."IdComprobantePartidaEgreso" INNER JOIN TT_AnularNominasTransferencias_p_RegistrosAProcesar AS RP ON RP."Id" = NT."IdNominaTransferencia" WHERE IE."IdIngresoEgreso" = CDO."IdIngresoEgreso")
